/**
 * PwaReloadPrompt — "New version available" banner.
 *
 * Boundary replaced: `virtual:pwa-register/react` (generated by vite-plugin-pwa at
 * build time; it does not exist under vitest). vitest.config.ts aliases it to
 * src/test-utils/pwa-register-react.ts, which keeps a real React state for
 * `needRefresh` and records the callbacks the component passes, so the component's
 * own banner / dismiss / re-show / polling logic runs for real.
 */
import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';
import { render, screen, fireEvent, act } from '@testing-library/react';
import { pwaRegisterControl as sw } from '@/test-utils/pwa-register-react';
import { PwaReloadPrompt } from '../pwa-reload-prompt';
import { expectAllControlsNamed } from './support/a11y';

const setVisibility = (v: 'visible' | 'hidden') => Object.defineProperty(document, 'visibilityState', { value: v, configurable: true });
const registration = () => ({ update: vi.fn(async () => {}) });
const asReg = (r: ReturnType<typeof registration>) => r as unknown as ServiceWorkerRegistration;

let warn: ReturnType<typeof vi.spyOn>;
let error: ReturnType<typeof vi.spyOn>;
beforeEach(() => {
  vi.useFakeTimers();
  sw.reset();
  setVisibility('visible');
  warn = vi.spyOn(console, 'warn').mockImplementation(() => {});
  error = vi.spyOn(console, 'error');
});
afterEach(() => {
  expect(error).not.toHaveBeenCalled();
  vi.useRealTimers();
  vi.restoreAllMocks();
});

describe('PwaReloadPrompt', () => {
  it('renders nothing while no update is waiting', () => {
    const { container } = render(<PwaReloadPrompt />);
    expect(container).toBeEmptyDOMElement();
    expect(warn).not.toHaveBeenCalled();
  });

  it('shows the banner when a new service worker is waiting; "Refresh now" activates it', () => {
    render(<PwaReloadPrompt />);
    act(() => { sw.setNeedRefresh!(true); });
    const banner = screen.getByRole('alertdialog', { name: 'New version available' });
    expect(banner).toHaveTextContent('Refresh to load the latest UI');
    fireEvent.click(screen.getByRole('button', { name: 'Refresh now' }));
    expect(sw.updateCalls).toEqual([true]);
    expect(warn).not.toHaveBeenCalled();
  });

  it('"Later" hides it, and a fresh notice inside the 5-minute window stays suppressed', () => {
    sw.initialNeedRefresh = true;
    render(<PwaReloadPrompt />);
    fireEvent.click(screen.getByRole('button', { name: 'Later' }));
    expect(screen.queryByRole('alertdialog')).toBeNull();
    act(() => { sw.setNeedRefresh!(true); });
    act(() => { vi.advanceTimersByTime(4 * 60_000); });
    expect(screen.queryByRole('alertdialog')).toBeNull();
    act(() => { vi.advanceTimersByTime(60_000); });
    expect(screen.getByRole('alertdialog', { name: 'New version available' })).toBeInTheDocument();
  });

  // D-L4: "Later" used to clear needRefresh as well, so the 5-minute re-show effect
  // returned early and never scheduled — one "Later" hid the prompt until the next
  // deploy, although the same waiting worker was still there.
  it('re-shows 5 minutes after "Later" while the SAME worker is still waiting', () => {
    sw.initialNeedRefresh = true;
    render(<PwaReloadPrompt />);
    fireEvent.click(screen.getByRole('button', { name: 'Later' }));
    expect(screen.queryByRole('alertdialog')).toBeNull();
    act(() => { vi.advanceTimersByTime(5 * 60_000 + 1_000); });
    expect(screen.getByRole('alertdialog', { name: 'New version available' })).toBeInTheDocument();
  });

  it('polls the registration every 60 s while visible, pauses when hidden, catches up on return', () => {
    render(<PwaReloadPrompt />);
    const reg = registration();
    act(() => { sw.options!.onRegisteredSW!('/sw.js', asReg(reg)); });
    act(() => { vi.advanceTimersByTime(120_000); });
    expect(reg.update).toHaveBeenCalledTimes(2);

    setVisibility('hidden');
    act(() => { document.dispatchEvent(new Event('visibilitychange')); });
    act(() => { vi.advanceTimersByTime(300_000); });
    expect(reg.update).toHaveBeenCalledTimes(2);
    // hiding twice is harmless
    act(() => { document.dispatchEvent(new Event('visibilitychange')); });

    setVisibility('visible');
    act(() => { document.dispatchEvent(new Event('visibilitychange')); });
    expect(reg.update).toHaveBeenCalledTimes(3); // immediate catch-up
    // a second "visible" catches up again but does not start a second interval
    act(() => { document.dispatchEvent(new Event('visibilitychange')); });
    expect(reg.update).toHaveBeenCalledTimes(4);
    act(() => { vi.advanceTimersByTime(60_000); });
    expect(reg.update).toHaveBeenCalledTimes(5);
  });

  it('does not poll when registered while the tab is hidden, until it becomes visible', () => {
    render(<PwaReloadPrompt />);
    setVisibility('hidden');
    const reg = registration();
    act(() => { sw.options!.onRegisteredSW!('/sw.js', asReg(reg)); });
    act(() => { vi.advanceTimersByTime(180_000); });
    expect(reg.update).not.toHaveBeenCalled();
  });

  it('ignores a registration callback without a registration object', () => {
    render(<PwaReloadPrompt />);
    expect(() => act(() => { sw.options!.onRegisteredSW!('/sw.js', undefined); })).not.toThrow();
  });

  it('logs a service-worker registration error as a warning', () => {
    render(<PwaReloadPrompt />);
    const err = new Error('SW blocked');
    sw.options!.onRegisterError!(err);
    expect(warn).toHaveBeenCalledWith('[pwa] SW register error:', err);
  });

  it('every control in the banner has an accessible name', () => {
    sw.initialNeedRefresh = true;
    const { container } = render(<PwaReloadPrompt />);
    expectAllControlsNamed(container);
  });
});
